const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

async function createAndArchive(base) {
  await api(base, "POST", "/api/links", { url: "https://example.com", slug: "link-a" });
  const resp = await api(base, "PATCH", "/api/links/link-a/archive");
  assert.strictEqual(resp.status, 200);
}

test("archived links: excluded from the list", async () => {
  const { base, close } = startServer();
  try {
    await createAndArchive(base);
    const resp = await api(base, "GET", "/api/links");
    assert.deepStrictEqual(resp.json, []);
  } finally {
    await close();
  }
});

test("archived links: direct fetch 404s", async () => {
  const { base, close } = startServer();
  try {
    await createAndArchive(base);
    const resp = await api(base, "GET", "/api/links/link-a");
    assert.strictEqual(resp.status, 404);
  } finally {
    await close();
  }
});

test("archived links: redirect 404s and records no click", async () => {
  const { base, close } = startServer();
  try {
    await createAndArchive(base);
    const resp = await api(base, "GET", "/r/link-a");
    assert.strictEqual(resp.status, 404);
  } finally {
    await close();
  }
});

